#!/bin/sh

# Xcode Cloud post-clone hook.
#
# LOCATION MATTERS: this MUST live at ios/App/ci_scripts/ — adjacent to
# App.xcodeproj — because Xcode Cloud looks for the ci_scripts folder in the
# same directory as the Xcode project, NOT at the repository root. A repo-root
# ci_scripts/ is silently ignored when the project sits in a subdirectory, so
# the hook never runs and the Archive step fails with "Project App.xcodeproj
# does not exist at ios/App/App.xcodeproj".
#
# The Capacitor ios/ tree is gitignored and regenerated by `cap`, so we
# generate it (web bundle + native project) here before Xcode Cloud archives.
# Only this ci_scripts/ folder is committed under ios/; everything else is
# produced below.
#
# The entire body is wrapped in a `{ ... }` group on purpose: the shell reads
# the whole compound command off disk BEFORE executing any of it, so the
# `rm -rf ios` that deletes this very file can't truncate the running script.
{
set -e

# Repo root (Xcode Cloud exports this).
cd "$CI_PRIMARY_REPOSITORY_PATH"

# Node isn't preinstalled on the Xcode Cloud image — install via Homebrew.
brew install node
node -v
npm -v

# Drop the sparse committed ios/ (this ci_scripts folder is the only tracked
# part) so `cap add ios` starts clean instead of erroring "already exists".
rm -rf ios

# Web bundle + native iOS project (mirrors `npm run setup:ios`).
npm ci
npm run build

# OTA (David 2026-07-03): stamp the SHIPPED bundle's version = short git SHA so
# it matches the OTA bundle published for this same commit
# (scripts/ci/publish-ota-bundle.mjs) — a fresh install won't redundantly
# re-download the bundle it already ships with. Read by capacitor.config.ts
# CapacitorUpdater.version, baked into the native project by `cap sync`.
export OTA_BUNDLE_VERSION="$(git -C "$CI_PRIMARY_REPOSITORY_PATH" rev-parse --short HEAD)"
echo "OTA_BUNDLE_VERSION=$OTA_BUNDLE_VERSION"

npx cap add ios
npx cap sync ios

# Regenerate the REAL app icon + splash from the committed sources in assets/.
# `cap add` scaffolds the DEFAULT Capacitor icon, so without this every build
# ships the placeholder icon (David's report 2026-06-13). The project's own
# asset pipeline builds the icon set into ios/App/App/Assets.xcassets.
npm run assets:generate

# Guard: FAIL the build if the brand icon wasn't actually applied. capacitor-
# assets can silently no-op for iOS (e.g. if it can't find the appiconset) and
# leave the white Capacitor placeholder — exactly what shipped in 2.8 (David
# 2026-06-14). This turns a wrong-icon ship into a red build.
node scripts/verify-app-icon.mjs

# Reapply the AVAudioSession AppDelegate patch (cap regenerates ios/).
cp ios-patches/App/AppDelegate.swift ios/App/App/AppDelegate.swift

# Pin the marketing version; Xcode Cloud auto-increments the build number
# (CFBundleVersion) to the build-run number every build on its own. Keeping ONE
# marketing version means each new build is the SAME version with a higher build
# number, so once this version clears Beta App Review the external testers get
# every subsequent build with NO re-review (David 2026-06-13). Bump this when you
# cut a real release; `cap add` scaffolds 1.0, which we must overwrite so it never
# regresses below the shipped 2.x line.
# NB (2026-06-22): builds #70/#71 were briefly rejected ("bundle version must be
# higher than previously uploaded") because the auto-increment counter had fallen
# behind the already-uploaded 2.8 build 72; it self-resolves once the run counter
# passes 72 (next build = 73 > 72). Do NOT try to override the build number here
# (epoch/agvtool tricks just fought the auto-increment and lost) — let Xcode Cloud
# own it.
# BUMP 2.8 → 3.0 (David 2026-07-08): 2.8 is RELEASED on the App Store, so Apple
# rejects any new build uploaded under that version ("must be a higher version").
# BUMP 3.0 → 3.1 (2026-07-11): 3.0 hit READY_FOR_SALE overnight (the nightly
# auto-submit released it), so Xcode Cloud runs #121/#122 died at
# PrepareBuildForAppStoreConnect — same released-version rejection as the 2.8
# incident. 3.1 carries the mic usage-string fix + half-duplex voice builds.
# (Nightly auto-submit is now disabled, so 3.1 won't self-release like 3.0 did.)
IOS_MARKETING_VERSION="3.1"
sed -i '' -e "s/MARKETING_VERSION = [^;]*;/MARKETING_VERSION = ${IOS_MARKETING_VERSION};/g" \
  ios/App/App.xcodeproj/project.pbxproj
echo "ci_post_clone: MARKETING_VERSION set to ${IOS_MARKETING_VERSION} (build ${CI_BUILD_NUMBER:-?})"

# Declare export compliance (standard HTTPS/TLS only = exempt encryption) so
# TestFlight never shows "Missing Compliance" and the build is installable for
# internal testers immediately, with no per-build encryption question. Guarded
# so a plist hiccup never aborts the archive.
PLIST="ios/App/App/Info.plist"
/usr/libexec/PlistBuddy -c "Add :ITSAppUsesNonExemptEncryption bool false" "$PLIST" 2>/dev/null \
  || /usr/libexec/PlistBuddy -c "Set :ITSAppUsesNonExemptEncryption false" "$PLIST" 2>/dev/null \
  || true

# Mic + speech-recognition usage strings — REQUIRED or the app crashes the
# instant @capacitor-community/speech-recognition requests permission (voice-to-
# coach in the native app — David 2026-06-18 "mic doesn't work in the iOS app").
# `cap add` regenerates Info.plist every build, so inject here (not in a
# committed plist). Add-then-Set so it's idempotent across re-runs.
#
# 🔒 ROOT CAUSE of the build-118 mic CRASH (David 2026-07-11, confirmed from the
# .ips): the crash was EXC_BREAKPOINT (brk 1) inside the plugin's
# `AVAudioSession.requestRecordPermission` completion — iOS's documented trap
# when a privacy API is called WITHOUT its Info.plist usage string. The old
# injection ended every line with `|| true`, so a wrong plist path or a
# PlistBuddy hiccup SILENTLY shipped a build with no usage string → guaranteed
# crash on the first mic tap. Never silent again: locate the real plist, inject,
# then VERIFY both keys are present and HARD-FAIL the build if either is missing.
MIC_MSG="Chess Academy uses the microphone so you can talk to your coach by voice."
SPEECH_MSG="Chess Academy uses speech recognition to turn what you say into messages for your coach."

# The plist path can drift with Capacitor versions; if the expected one is
# missing, find the real App Info.plist rather than inject into the void.
if [ ! -f "$PLIST" ]; then
  ALT_PLIST="$(find ios -name "Info.plist" -path "*App/App*" 2>/dev/null | head -1)"
  echo "ci_post_clone: expected $PLIST missing; discovered '$ALT_PLIST'"
  [ -n "$ALT_PLIST" ] && PLIST="$ALT_PLIST"
fi

/usr/libexec/PlistBuddy -c "Add :NSMicrophoneUsageDescription string \"$MIC_MSG\"" "$PLIST" 2>/dev/null \
  || /usr/libexec/PlistBuddy -c "Set :NSMicrophoneUsageDescription \"$MIC_MSG\"" "$PLIST" 2>/dev/null || true
/usr/libexec/PlistBuddy -c "Add :NSSpeechRecognitionUsageDescription string \"$SPEECH_MSG\"" "$PLIST" 2>/dev/null \
  || /usr/libexec/PlistBuddy -c "Set :NSSpeechRecognitionUsageDescription \"$SPEECH_MSG\"" "$PLIST" 2>/dev/null || true

# VERIFY — read the keys back. If either is absent the app WILL crash on mic use,
# so make it a RED BUILD instead of a shipped crash.
MIC_CHECK="$(/usr/libexec/PlistBuddy -c "Print :NSMicrophoneUsageDescription" "$PLIST" 2>/dev/null || echo "")"
SPEECH_CHECK="$(/usr/libexec/PlistBuddy -c "Print :NSSpeechRecognitionUsageDescription" "$PLIST" 2>/dev/null || echo "")"
if [ -z "$MIC_CHECK" ] || [ -z "$SPEECH_CHECK" ]; then
  echo "ci_post_clone: FATAL — mic/speech usage strings NOT present in $PLIST"
  echo "  NSMicrophoneUsageDescription='$MIC_CHECK'"
  echo "  NSSpeechRecognitionUsageDescription='$SPEECH_CHECK'"
  echo "  The app would EXC_BREAKPOINT on the first mic tap (build-118 crash). Aborting."
  ls -la "$(dirname "$PLIST")" || true
  exit 1
fi
echo "ci_post_clone: verified mic + speech usage strings present in $PLIST"

# --- Swift Package resolution -------------------------------------------------
# Xcode Cloud archives with "only use versions from Package.resolved" forced ON
# globally (IDEPackageOnlyUseVersionsFromResolvedFile), so the Archive step
# REFUSES to resolve fresh and demands a resolved file at
#   App.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved
# Because the project is generated here, none is committed — so we must produce
# it now. (This global setting is why an explicit
# `xcodebuild -resolvePackageDependencies` alone failed with exit 74 — see
# swift-package-manager#6914.)
RESOLVED="ios/App/App.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved"

# Flip the global default OFF for this build user so xcodebuild can resolve,
# then resolve — this writes Package.resolved with the originHash xcodebuild
# expects for the .xcodeproj dependency graph.
defaults write com.apple.dt.Xcode IDEPackageOnlyUseVersionsFromResolvedFile -bool NO || true
xcodebuild -resolvePackageDependencies -project ios/App/App.xcodeproj -scheme App || true

# Fallback: if the above didn't produce the file (e.g. the default is enforced
# another way), resolve with the SwiftPM CLI — it ignores the com.apple.dt.Xcode
# default entirely — and place the result where the Archive step looks.
if [ ! -f "$RESOLVED" ]; then
  ( cd ios/App/CapApp-SPM && xcrun swift package resolve )
  mkdir -p "$(dirname "$RESOLVED")"
  cp ios/App/CapApp-SPM/Package.resolved "$RESOLVED"
fi

test -f "$RESOLVED" || { echo "ci_post_clone: FAILED to produce Package.resolved"; exit 1; }

echo "ci_post_clone: generated ios/App/App.xcodeproj + resolved SPM dependencies"
}
